3	namespace App\Services\Billing;
4	
5	use App\Models\Billing\Subscription;
6	use App\Models\Core\Professional\Professional;
7	
8	// V2: Subscription tier checks and feature entitlement resolution. Gates premium features by plan level.
9	class Entitlements
10	{
11	    private const TIER_RANK = ['free' => 0, 'professional' => 1, 'brands' => 2];
12	
13	    /** @var array<string, Subscription|null> Per-request cache keyed by professional ID */
14	    private array $cache = [];
15	
16	    public function currentSubscription(Professional $professional): ?Subscription
17	    {
18	        $key = $professional->id;
19	
20	        if (! array_key_exists($key, $this->cache)) {
21	            $this->cache[$key] = Subscription::query()
22	                ->with('plan')
23	                ->where('professional_id', $professional->id)
24	                ->whereNull('ended_at')
25	                ->latest('created_at')
26	                ->first();
27	        }
28	
29	        return $this->cache[$key];
30	    }
31	
32	    public function clearCache(?string $professionalId = null): void
33	    {
34	        if ($professionalId) {
35	            unset($this->cache[$professionalId]);
36	        } else {
37	            $this->cache = [];
38	        }
39	    }
40	
41	    public function hasPlan(Professional $professional, string $minPlanKey): bool
42	    {
43	        $sub = $this->currentSubscription($professional);
44	
45	        if (! $sub || ! $sub->isInGracePeriod()) {
46	            return $minPlanKey === 'free';
47	        }
48	
49	        $planKey = $sub->plan?->plan_key ?? 'free';
50	
51	        return (self::TIER_RANK[$planKey] ?? 0) >= (self::TIER_RANK[$minPlanKey] ?? 999);
52	    }
53	
54	    public function hasEntitlement(Professional $professional, string $key): bool
55	    {
56	        $sub = $this->currentSubscription($professional);
57	
58	        if (! $sub || ! $sub->isInGracePeriod()) {
59	            return false;
60	        }
61	
62	        $ents = $sub->plan?->entitlements ?? [];
63	
64	        if (! array_key_exists($key, $ents)) {
65	            return false;
66	        }
67	
68	        return (bool) $ents[$key];
69	    }
70	
71	    public function entitlementLimit(Professional $professional, string $key): ?int
72	    {
73	        $sub = $this->currentSubscription($professional);
74	        $ents = $sub?->plan?->entitlements ?? [];
75	
76	        if (! array_key_exists($key, $ents)) {
77	            return null;
78	        }
79	
80	        $value = $ents[$key];
81	
82	        return is_numeric($value) ? (int) $value : null;
83	    }
84	
85	    public function isWithinLimit(Professional $professional, string $key, int $currentCount): bool
86	    {
87	        $limit = $this->entitlementLimit($professional, $key);
88	
89	        if ($limit === null) {
90	            return true; // no limit = unlimited
91	        }
92	
93	        return $currentCount < $limit;
94	    }
95	}
